probes.shared:
type Node struct {
	Vals []int64
}
s := &Node{Vals: []int64{1, 2, 3}}
v := []*Node{s, s}
v[0].Vals = append(v[0].Vals, 99)
r := "copied"
if len(v[1].Vals) == 4 && v[1].Vals[3] == 99 {
	r = "shared"
}

